input.old_string:
:root {
  --c: #0f6b5c;
  --w: #ffffff;
}

.page-bg { background: var(--w); }
.header-bar { background: var(--c); border-bottom: 2px solid var(--c); }
.header-title { color: var(--w); }
.header-sub { color: var(--w); }

.nav-link {
  padding: 2px 8px; border-radius: 4px; font-size: 12px; text-decoration: none;
  color: var(--w); border: 1px solid var(--w); background: transparent;
}
.nav-link:hover { background: var(--w); color: var(--c); }
.nav-link-accent { background: var(--w); color: var(--c); font-weight: 700; }

.group-label {
  font-size: 10px; font-weight: 800; letter-spacing: 0.08em;
  text-transform: uppercase; padding: 3px 8px; border-radius: 4px;
  background: var(--c); color: var(--w);
}
.group-label-outline {
  background: var(--w); color: var(--c); border: 1px solid var(--c);
}

.card { background: var(--w); border: 2px solid var(--c); border-radius: 8px; overflow: hidden; }
.card-head { background: var(--c); color: var(--w); }
.card-head-sub { color: var(--w); font-size: 12px; }

.code-block { background: var(--w); color: var(--c); border-top: 1px solid var(--c); }

.hl { color: var(--c); font-weight: 700; }
.hl-cmt { color: var(--c); font-style: italic; font-weight: 400; }

.copy-btn {
  background: var(--w); color: var(--c); border: 1px solid var(--w);
  padding: 4px 12px; font-size: 12px; border-radius: 4px; cursor: pointer; font-weight: 600;
}
.copy-btn:hover { background: var(--c); color: var(--w); border-color: var(--w); }
.copy-btn.copied { background: var(--w); color: var(--c); border: 2px solid var(--w); }

.info-box { background: var(--w); border: 2px solid var(--c); border-radius: 8px; color: var(--c); }

